mutations.find:
read(cursor: string | undefined): Promise<SourceRead<T>> {
  return this.inner.read(cursor ?? this.start);
}

mutations.replace:
async read(cursor: string | undefined): Promise<SourceRead<T>> {
  if (cursor !== undefined) return this.inner.read(cursor);
  const now = await this.inner.read(undefined);
  return this.inner.read(now.cursor);
}
